insert into public.product_variants (id, product_id, sku, name, price_cents, compare_at_price_cents, stock, position) values ('2249e509-a736-41ca-b4af-592bc142ff24', '5ebf0ff0-8228-4e27-953e-2f2622f77a85', 'HDM-TRT-4', '4 personas', 2490, null, 22, 1) on conflict (id) do nothing;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('6d81490b-c95a-487a-a88c-c70133745a78', 'kit-penne-arrabbiata', 'Kit Penne all''arrabbiata', 'La salsa de tomate picante más famosa de Roma.', 'Penne rigate de trigo duro, tomate triturado italiano y nuestra mezcla de guindilla y ajo deshidratado. Aprendes a sofreír sin quemar y a ligar la salsa con el agua de la pasta como en Italia.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', false, true, null, 140, '{"minutes":20,"difficulty":2,"heat":"cazo","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite de oliva."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'picante']::text[], array['gluten']::text[], array[]::text[], array[]::text[], '{"youAdd":["2 litros de agua","3 cucharadas de aceite de oliva"],"steps":[{"title":"Agua a hervir","text":"Pon a hervir 2 litros de agua con una cucharada de sal en un cazo grande."},{"title":"Sofrito","text":"En una sartén, calienta el aceite a fuego bajo con el ajo y la guindilla 1 minuto. Si el ajo se tuesta demasiado, amarga."},{"title":"Salsa","text":"Añade el tomate triturado y cocina 10 minutos a fuego medio, removiendo de vez en cuando."},{"title":"Pasta","text":"Cuece los penne el tiempo del paquete menos un minuto. Antes de escurrir, guarda medio vaso del agua de cocción."},{"title":"Liga","text":"Echa la pasta a la salsa con un chorrito del agua guardada y remueve a fuego fuerte 1 minuto hasta que brille. Perejil y a la mesa."}],"tips":["El agua de la pasta tiene almidón: es lo que hace que la salsa se pegue."]}'::jsonb, array['Penne rigate', 'Tomate triturado italiano (brik)', 'Sobre de guindilla y ajo', 'Sobre de perejil', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Penne all''arrabbiata kit","subtitle":"Rome’s most famous spicy tomato sauce.","description":"Durum wheat penne rigate, Italian chopped tomatoes and our mix of chilli and dried garlic. You learn to fry gently without burning and to bind the sauce with pasta water, the Italian way.","includes":["Penne rigate","Italian chopped tomatoes (carton)","Chilli and garlic sachet","Parsley sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and olive oil."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["2 litres water","3 tablespoons olive oil"],"steps":[{"title":"Boil the water","text":"Bring 2 litres of water with a tablespoon of salt to the boil in a big pot."},{"title":"The base","text":"In a pan, warm the oil on low heat with the garlic and chilli for 1 minute. If the garlic gets too dark, it turns bitter."},{"title":"Sauce","text":"Add the chopped tomatoes and cook for 10 minutes on medium heat, stirring now and then."},{"title":"Pasta","text":"Cook the penne for the packet time minus one minute. Before draining, save half a glass of the cooking water."},{"title":"Bring it together","text":"Add the pasta to the sauce with a splash of the saved water and stir on high heat for 1 minute until glossy. Parsley, and serve."}],"tips":["Pasta water is full of starch: that’s what makes the sauce stick."]},"variants":{"HDM-PEN-2":"Serves 2","HDM-PEN-4":"Serves 4"},"imageAlts":["Plate of penne with tomato sauce","Pan with pasta"]}}'::jsonb, now() - interval '80 days', now() - interval '80 days') on conflict (id) do update set translations = excluded.translations;
