insert into public.product_variants (id, product_id, sku, name, price_cents, compare_at_price_cents, stock, position) values ('93671808-2d32-45d7-b6cf-41f24dac8439', '6d81490b-c95a-487a-a88c-c70133745a78', 'HDM-PEN-4', '4 personas', 2890, null, 0, 1) on conflict (id) do nothing;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('6cfd3f8d-ac78-49c4-a15e-66bb244919da', 'kit-falafel-pita', 'Kit Falafel con pita', 'Falafel crujiente a la sartén, pan de pita, salsa de tahini y encurtidos.', 'La mezcla de falafel lleva garbanzo, hierbas y especias: solo añades agua, formas las bolitas y las doras en la sartén. Rellenas el pan de pita con los falafels, la salsa de tahini, los pepinillos y una pizca de zumaque. Todo de despensa.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', false, true, 'Nuevo', 16, '{"minutes":25,"difficulty":2,"heat":"sarten","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'vegetariano']::text[], array['gluten', 'sesamo']::text[], array['mostaza']::text[], array[]::text[], '{"youAdd":["150 ml de agua","4 cucharadas de aceite"],"steps":[{"title":"Hidrata la mezcla","text":"Mezcla el falafel con 150 ml de agua y deja reposar 10 minutos: tiene que quedar una masa que se pueda moldear."},{"title":"Forma las bolitas","text":"Con las manos húmedas, haz bolitas del tamaño de una nuez y aplánalas un poco."},{"title":"Dóralas","text":"Sartén con el aceite a fuego medio. Dora los falafels 3 minutos por cada lado y sácalos a un papel de cocina."},{"title":"Calienta el pan","text":"Unos segundos en la sartén, sin aceite, para que se abra mejor."},{"title":"Rellena","text":"Abre la pita, pon 3 o 4 falafels, salsa de tahini, pepinillos y una pizca de zumaque."}],"tips":["Si la masa se deshace, añade una cucharadita más de la mezcla seca.","No los muevas hasta que estén dorados: así no se rompen."]}'::jsonb, array['Mezcla para falafel (garbanzo, hierbas y especias)', 'Pan de pita', 'Sobre de salsa de tahini', 'Pepinillos encurtidos', 'Sobre de zumaque', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Falafel and pita kit","subtitle":"Crispy pan-fried falafel, pita bread, tahini sauce and pickles.","description":"The falafel mix has chickpeas, herbs and spices: just add water, shape the balls and fry them in a pan. Fill the pita with the falafel, tahini sauce, pickles and a pinch of sumac. All from the cupboard.","badge":"New","includes":["Falafel mix (chickpeas, herbs and spices)","Pita bread","Tahini sauce sachet","Pickled gherkins","Sumac sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and oil."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["150 ml water","4 tablespoons oil"],"steps":[{"title":"Hydrate the mix","text":"Mix the falafel with 150 ml water and leave for 10 minutes: you want a dough you can shape."},{"title":"Shape the balls","text":"With damp hands, make walnut-sized balls and flatten them slightly."},{"title":"Fry them","text":"Pan with the oil on medium heat. Fry the falafel for 3 minutes each side and drain on kitchen paper."},{"title":"Warm the bread","text":"A few seconds in the dry pan so it opens more easily."},{"title":"Fill","text":"Open the pita and add 3 or 4 falafel, tahini sauce, gherkins and a pinch of sumac."}],"tips":["If the dough falls apart, add another teaspoon of the dry mix.","Don’t move them until they’re golden: that way they don’t break."]},"variants":{"HDM-FAL-2":"Serves 2","HDM-FAL-4":"Serves 4"},"imageAlts":["Golden falafel, one split in half","Bowl of falafel with pickles (serving suggestion)"]}}'::jsonb, now() - interval '5 days', now() - interval '5 days') on conflict (id) do update set translations = excluded.translations;
