insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('9cd23a54-a303-49f7-8245-387ac19888f5', 'kit-curry-rojo-thai', 'Kit Curry rojo de salmón', 'Salmón fresco en curry rojo tailandés con leche de coco y arroz jazmín.', 'Un viaje a Bangkok en 35 minutos. Nivel 3: el kit trae el salmón fresco y el limón, además de la pasta de curry rojo, la leche de coco, el arroz jazmín y las hierbas. Aprendes a marcar el pescado sin que se rompa y a equilibrar dulce, salado, ácido y picante.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', true, true, 'Nuevo', 30, '{"minutes":35,"difficulty":3,"heat":"sarten","storage":"fresco"}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['picante', 'sin-gluten']::text[], array['pescado', 'crustaceos']::text[], array[]::text[], array[]::text[], '{"youAdd":["Agua para el arroz","1 cucharada de aceite"],"steps":[{"title":"Arroz jazmín","text":"Lava el arroz bajo el grifo hasta que el agua salga clara. Cuécelo con 1,5 veces su volumen de agua, tapado y a fuego bajo, 12 minutos. Reposa 5."},{"title":"Seca el salmón","text":"Saca el salmón de la nevera, sécalo bien con papel de cocina y ponle una pizca de sal. Seco se dora mejor y no salpica."},{"title":"Marca el salmón","text":"Sartén a fuego medio-alto con el aceite. Pon los lomos con la piel hacia abajo 3 minutos sin moverlos, dales la vuelta 1 minuto y sácalos a un plato."},{"title":"La salsa","text":"En la misma sartén, baja el fuego y remueve la pasta de curry 1 minuto. Añade la leche de coco y cocina 5 minutos hasta que espese un poco."},{"title":"Junta todo","text":"Vuelve a meter el salmón en la salsa 4 minutos a fuego suave. Está listo cuando se separa en láminas al tocarlo con un tenedor."},{"title":"Sirve","text":"Unas rodajas de limón y el orégano fresco por encima, y el arroz al lado."}],"tips":["Mueve el salmón lo menos posible: si lo tocas mucho, se rompe.","Si pica demasiado, añade más leche de coco."]}'::jsonb, array['Lomos de salmón frescos', 'Limón', 'Pasta de curry rojo', 'Leche de coco', 'Arroz jazmín', 'Orégano fresco', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Red salmon curry kit","subtitle":"Fresh salmon in Thai red curry with coconut milk and jasmine rice.","description":"A trip to Bangkok in 35 minutes. Level 3: the kit brings the fresh salmon and lemon, plus red curry paste, coconut milk, jasmine rice and herbs. You learn to sear fish without it falling apart and to balance sweet, salty, sour and spicy.","badge":"New","includes":["Fresh salmon fillets","Lemon","Red curry paste","Coconut milk","Jasmine rice","Fresh oregano","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and oil."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["Water for the rice","1 tablespoon oil"],"steps":[{"title":"Jasmine rice","text":"Rinse the rice under the tap until the water runs clear. Cook it with 1.5 times its volume of water, covered, on low heat for 12 minutes. Rest for 5."},{"title":"Dry the salmon","text":"Take the salmon out of the fridge, pat it very dry with kitchen paper and add a pinch of salt. Dry fish browns better and doesn’t spit."},{"title":"Sear the salmon","text":"Pan on medium-high heat with the oil. Place the fillets skin side down for 3 minutes without moving them, flip for 1 minute and set aside on a plate."},{"title":"The sauce","text":"In the same pan, lower the heat and stir the curry paste for 1 minute. Add the coconut milk and cook for 5 minutes until it thickens slightly."},{"title":"Bring it together","text":"Return the salmon to the sauce for 4 minutes on gentle heat. It’s ready when it flakes when you touch it with a fork."},{"title":"Serve","text":"A few lemon slices and the fresh oregano on top, with the rice on the side."}],"tips":["Move the salmon as little as possible: if you keep touching it, it breaks.","Too spicy? Add more coconut milk."]},"variants":{"HDM-CUR-2":"Serves 2","HDM-CUR-4":"Serves 4"},"imageAlts":["Salmon fillets in red curry sauce with lemon slices","Pan of curry with fresh herbs"]}}'::jsonb, now() - interval '4 days', now() - interval '4 days') on conflict (id) do update set translations = excluded.translations;
