insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('8d6b83ec-d10f-4c29-a237-b8921c573207', 'kit-yakisoba', 'Kit Yakisoba', 'Fideos salteados al wok con verduras frescas y salsa yakisoba.', 'Fideos de trigo salteados a fuego fuerte con verduras frescas (col, zanahoria, pimiento y cebolla, ya incluidas) y salsa yakisoba casera. Aprendes la técnica del salteado: todo cortado antes, sartén muy caliente y movimiento constante.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 88, '{"minutes":25,"difficulty":3,"heat":"sarten","storage":"fresco"}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano']::text[], array['gluten', 'soja', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["Agua para los fideos","2 cucharadas de aceite"],"steps":[{"title":"Corta todo antes","text":"Col en tiras, zanahoria en bastones finos, pimiento y cebolla en tiras. El salteado va tan rápido que no da tiempo después."},{"title":"Fideos","text":"Cuécelos 3 minutos, escúrrelos y pásalos por agua fría para que no se peguen."},{"title":"Sartén muy caliente","text":"Aceite a fuego fuerte. Saltea la cebolla y la zanahoria 2 minutos sin parar de mover."},{"title":"Resto de verduras","text":"Añade la col, el pimiento y el jengibre. 2 minutos más: deben quedar crujientes."},{"title":"Todo junto","text":"Fideos y salsa yakisoba. Mezcla 1 minuto a fuego fuerte y termina con sésamo tostado."}],"tips":["Si tu sartén es pequeña, hazlo en dos tandas: si la llenas, las verduras se cuecen en vez de saltearse."]}'::jsonb, array['Fideos de trigo', 'Col, zanahoria, pimiento y cebolla frescos', 'Salsa yakisoba', 'Jengibre', 'Sobre de sésamo tostado', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Yakisoba kit","subtitle":"Wok-fried noodles with fresh veg and yakisoba sauce.","description":"Wheat noodles stir-fried on high heat with fresh veg (cabbage, carrot, pepper and onion, all included) and homemade-style yakisoba sauce. You learn stir-frying: everything cut first, a very hot pan and constant movement.","includes":["Wheat noodles","Fresh cabbage, carrot, pepper and onion","Yakisoba sauce","Ginger","Toasted sesame sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and oil."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["Water for the noodles","2 tablespoons oil"],"steps":[{"title":"Cut everything first","text":"Cabbage in strips, carrot in thin sticks, pepper and onion in strips. Stir-frying is so fast there’s no time later."},{"title":"Noodles","text":"Cook for 3 minutes, drain and rinse under cold water so they don’t stick."},{"title":"Very hot pan","text":"Oil on high heat. Stir-fry the onion and carrot for 2 minutes, keeping everything moving."},{"title":"The rest of the veg","text":"Add the cabbage, pepper and ginger. 2 more minutes: they should stay crunchy."},{"title":"All together","text":"Noodles and yakisoba sauce. Toss for 1 minute on high heat and finish with toasted sesame."}],"tips":["If your pan is small, do it in two batches: overcrowded veg steam instead of frying."]},"variants":{"HDM-YAK-2":"Serves 2","HDM-YAK-4":"Serves 4"},"imageAlts":["Stir-fried noodles on a black plate","Bowl of noodles with lime and veg"]}}'::jsonb, now() - interval '50 days', now() - interval '50 days') on conflict (id) do update set translations = excluded.translations;
