insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('f7c42a94-a86f-4b8f-9b76-a3a253aa61bd', 'kit-smash-burgers', 'Kit Smash burgers', 'Carne fresca aplastada a la plancha, cheddar fundido y pan brioche.', 'Las hamburguesas de moda: bolas de carne de vacuno fresca que se aplastan en la sartén muy caliente para que queden con costra. Llega refrigerado con la carne, el cheddar, el pan brioche y la cebolla; además, pepinillos, salsa burger y un sobre de sal y pimienta.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', true, true, 'Nuevo', 40, '{"minutes":30,"difficulty":3,"heat":"sarten","storage":"fresco"}'::jsonb, '[{"label":"Tú pones","value":"Un chorrito de aceite."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array[]::text[], array['gluten', 'leche', 'huevos', 'mostaza', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["1 cucharada de aceite"],"steps":[{"title":"Haz las bolas","text":"Divide la carne en bolas iguales (2 por hamburguesa). No la amases: cuanto menos la toques, más jugosa."},{"title":"Prepara todo","text":"Corta la cebolla en aros muy finos, abre los panes y ten a mano el queso: luego va todo muy rápido."},{"title":"Tuesta el pan","text":"Sartén caliente sin aceite: tuesta el pan por la cara de dentro 1 minuto y resérvalo."},{"title":"Aplasta","text":"Sube el fuego al máximo con un chorrito de aceite. Pon las bolas y aplástalas con una espátula hasta dejarlas finas. Sal y pimienta."},{"title":"Vuelta y queso","text":"A los 2 minutos, cuando tengan costra, dales la vuelta, pon el cheddar encima y 1 minuto más."},{"title":"Monta","text":"Pan, salsa burger, dos carnes con queso, cebolla, pepinillos y tapa. ¡A por ella!"}],"tips":["La sartén tiene que estar muy caliente: si no humea un poco, espera.","Lávate las manos después de tocar la carne cruda."]}'::jsonb, array['Carne picada de vacuno fresca', 'Pan brioche', 'Lonchas de queso cheddar', 'Cebolla roja fresca', 'Pepinillos encurtidos', 'Sobre de salsa burger', 'Sobre de sal y pimienta', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Smash burgers kit","subtitle":"Fresh beef smashed on a hot pan, melted cheddar and brioche buns.","description":"The burger everyone’s talking about: balls of fresh beef smashed in a very hot pan for a crispy crust. It arrives chilled with the beef, cheddar, brioche buns and onion, plus pickles, burger sauce and a salt and pepper sachet.","badge":"New","includes":["Fresh minced beef","Brioche buns","Cheddar slices","Fresh red onion","Pickled gherkins","Burger sauce sachet","Salt and pepper sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"A splash of oil."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["1 tablespoon oil"],"steps":[{"title":"Make the balls","text":"Split the beef into equal balls (2 per burger). Don’t knead it: the less you handle it, the juicier it stays."},{"title":"Get everything ready","text":"Slice the onion into very thin rings, open the buns and have the cheese at hand: it all goes fast after this."},{"title":"Toast the buns","text":"Hot pan, no oil: toast the cut side of the buns for 1 minute and set aside."},{"title":"Smash","text":"Turn the heat to max with a splash of oil. Add the balls and press them flat with a spatula. Salt and pepper."},{"title":"Flip and cheese","text":"After 2 minutes, when they have a crust, flip them, put the cheddar on top and cook 1 more minute."},{"title":"Build","text":"Bun, burger sauce, two cheesy patties, onion, gherkins and the lid. Dig in!"}],"tips":["The pan has to be really hot: if it isn’t smoking a little, wait.","Wash your hands after touching raw meat."]},"variants":{"HDM-SMB-2":"Serves 2","HDM-SMB-4":"Serves 4"},"imageAlts":["Double smash burger with cheddar and gherkins","Double cheeseburger in a sesame bun"]}}'::jsonb, now() - interval '2 days', now() - interval '2 days') on conflict (id) do update set translations = excluded.translations;
